def clean_str(s):
    if not s:
        return ""
    s = str(s).lower()
    for a, b in [
        ("thùng carton box", "carton box"),
        ("thung carton box", "carton box"),
        ("tấm lót pad", "pad"),
        ("tam lot pad", "pad"),
        ("tấm lót", "pad"),
        ("tam lot", "pad"),
        ("tấm inner pad", "inner pad"),
        ("tam inner pad", "inner pad"),
        ("không in", ""),
        ("khong in", ""),
    ]:
        s = s.replace(a, b)
    return re.sub(r"[^a-z0-9]", "", s)


def strip_accents_upper(t):
    import unicodedata
    if not t:
        return ""
    nfd = unicodedata.normalize("NFD", str(t))
    without = "".join(c for c in nfd if unicodedata.category(c) != "Mn")
    return without.replace("đ", "d").replace("Đ", "D").upper()


def num_to_vn_words(num):
    if not num or num <= 0:
        return "Không đồng"
    d = ["không", "một", "hai", "ba", "bốn", "năm", "sáu", "bảy", "tám", "chín"]

    def read_three(n, full):
        tr = n // 100
        ch = (n % 100) // 10
        dv = n % 10
        out = []
        if tr or full:
            out.append(d[tr] + " trăm")
        if ch > 1:
            out.append(d[ch] + " mươi")
        elif ch == 1:
            out.append("mười")
        elif (tr or full) and dv:
            out.append("lẻ")
        if dv:
            if dv == 1 and ch > 1:
                out.append("mốt")
            elif dv == 5 and ch >= 1:
                out.append("lăm")
            else:
                out.append(d[dv])
        return " ".join(out)

    units = ["", " nghìn", " triệu", " tỷ"]
    n = int(round(num))
    groups = []
    while n > 0:
        groups.append(n % 1000)
        n //= 1000
    parts = []
    started = False
    for g in range(len(groups) - 1, -1, -1):
        if groups[g]:
            parts.append(read_three(groups[g], started) + units[g % 4])
            started = True
    txt = re.sub(r"\s+", " ", " ".join(parts)).strip()
    return txt[0].upper() + txt[1:] + " đồng"


