# 3. BỘ QUÉT & PHÂN TÍCH PO OFFLINE 100% TRÊN DESKTOP (GIỮ NGUYÊN LOGIC BẢN GỐC)
# ==============================================================================
def extract_text_from_pdf_or_image_offline(file_path, is_tesa=False):
    ext = os.path.splitext(file_path)[1].lower()
    if ext in (".png", ".jpg", ".jpeg", ".bmp", ".tif", ".tiff"):
        if pytesseract is not None:
            try:
                from PIL import Image
                return pytesseract.image_to_string(Image.open(file_path), lang="vie+eng")
            except Exception:
                pass
        return ""

    pages_out = []
    if pypdf is not None:
        try:
            reader = pypdf.PdfReader(file_path)
            total = len(reader.pages)
            page_indices = (
                [i for i in range(1, total, 2)]
                if is_tesa and total >= 2
                else list(range(min(total, 10)))
            )
            for idx in page_indices:
                embedded = (reader.pages[idx].extract_text() or "").strip()
                if len(re.sub(r"\s+", "", embedded)) > 80:
                    pages_out.append(embedded)
                elif pdfium is not None and pytesseract is not None:
                    doc = pdfium.PdfDocument(file_path)
                    page = doc[idx]
                    pil_img = page.render(scale=3.0 if is_tesa else 2.5).to_pil()
                    ocr_txt = pytesseract.image_to_string(pil_img, lang="vie+eng")
                    if is_tesa:
                        w, h = pil_img.size
                        strip = pil_img.crop((0, int(h * 0.085), int(w * 0.8), int(h * 0.175)))
                        strip = strip.resize((strip.width * 2, strip.height * 2))
                        hdr_txt = pytesseract.image_to_string(strip, lang="eng")
                        ocr_txt += "\n@@HDR@@\n" + hdr_txt
                    pages_out.append(ocr_txt)
        except Exception:
            pass

    if not pages_out:
        try:
            with open(file_path, "rb") as f:
                raw = f.read()
            latin = raw.decode("latin1", errors="ignore")
            chunks = [m.group(1) for m in re.finditer(r"\(([^()]{2,200})\)", latin)]
            utf_txt = raw.decode("utf-8", errors="ignore")
            pages_out.append(" ".join(chunks) + "\n" + utf_txt)
        except Exception:
            pass
    return "\n@@PAGE@@\n".join(pages_out)


def parse_kodi_po_text(text, kodi_catalog, data_store=None, tare_val=1.0):
    po_no = ""
    po_date = ""
    m1 = re.search(r"(\d{8}\s*-\s*\d{1,2}\s*[A-Za-z]{2,})", text)
    if m1:
        po_no = re.sub(r"\s+", "", m1.group(1)).upper()
    m2 = re.search(r"ng[àa]y\W{0,4}(\d{1,2})\s*th[áa]ng\s*(\d{1,2})\s*n[ăa]m\s*(\d{4})", text, re.I)
    if m2:
        po_date = f"{int(m2.group(1)):02d}/{int(m2.group(2)):02d}/{m2.group(3)}"

    lines = []
    for raw_line in text.splitlines():
        nm = re.search(r"(?:Ống|Ong|Óng|Bìa)\s*giấy.*?mm", raw_line, re.I)
        if not nm:
            continue
        name = re.sub(r"^(Óng|Ong)", "Ống", nm.group(0), flags=re.I)
        name = re.sub(r"\s*x\s*", " x ", name, flags=re.I)
        name = re.sub(r"\s+", " ", name).strip()
        rest = raw_line[nm.end():]
        money = [int(re.sub(r"[.,]", "", x)) for x in re.findall(r"\d{1,3}(?:[.,]\d{3})+", rest)]
        plain = [int(x) for x in re.findall(r"(?<![\d.,])\d{1,6}(?![\d.,])", rest)]
        price, amount, qty = 0, 0, 0
        if len(money) >= 2:
            price, amount = money[-2], money[-1]
        elif len(money) == 1:
            price = money[0]
        known = next((x for x in kodi_catalog if x["name"].replace(" ", "").lower() == name.replace(" ", "").lower()), None)
        if known and not price:
            price = known["price"]
        if price and amount and amount % price == 0:
            qty = amount // price
        elif plain:
            qty = plain[0]
        if qty > 0:
            item_name = known["name"] if known else name
            mem = data_store.get_item_norm(item_name) if data_store else None
            div = mem["div"] if (mem and mem.get("div")) else (known["div"] if known else 5)
            kg = mem["kg"] if (mem and mem.get("kg")) else (known["kg"] if known else 1.96)
            kien = math.ceil(round(qty / div * 1e6) / 1e6) if div > 0 else 0
            net = round(qty * kg, 2) if kg > 0 else 0.0
            gross = round(net + tare_val, 2) if net > 0 else 0.0
            lines.append({
                "stt": len(lines) + 1,
                "po": po_no,
                "hs": (mem.get("hs") if mem else None) or (known.get("hs", "48229090") if known else "48229090"),
                "ma_sp": known.get("code", "") if known else "",
                "ten_sp": item_name,
                "ten_hq": known.get("ten_hq", item_name) if known else item_name,
                "unit": "chiếc",
                "qty": qty,
                "price": price,
                "amount": qty * price,
                "div": div,
                "kg": kg,
                "kien": kien,
                "net": net,
                "gross": gross,
                "tare": tare_val,
            })
    return po_no, po_date, lines


def parse_tesa_po_page(t0):
    parts = t0.split("@@HDR@@")
    t = parts[0]
    hdr = parts[1] if len(parts) > 1 else ""
    m_main = re.search(r"Purchase\s*Order:?\s*(8600\d{6})", t, re.I) or re.search(r"\b(8600\d{6})\b", t)
    m_hdr = re.search(r"\b(8600\d{6})\b", hdr)
    po_main = m_main.group(1) if m_main else ""
    po_hdr = m_hdr.group(1) if m_hdr else ""
    po = po_hdr or po_main
    lines = t.splitlines()
    li = next((i for i, l in enumerate(lines) if re.search(r"\b\d{5}-\d{5}-\d{2}\b", l)), -1)
    if not po or li < 0:
        return None
    line = lines[li]
    code = re.search(r"\b\d{5}-\d{5}-\d{2}\b", line).group(0)
    ix = line.find(code)

    def parse_money(x):
        d = re.sub(r"\D", "", str(x))
        return int(d[:-2]) + int(d[-2:]) / 100.0 if len(d) > 2 else 0.0

    def parse_int(x):
        d = re.sub(r"\D", "", str(x))
        return int(d) if d else 0

    before = [parse_int(x) for x in re.findall(r"\d[\d,.]*", line[:ix])]
    after = line[ix + len(code):]
    dec = [parse_money(x) for x in re.findall(r"\d[\d,.]*[.,]\d{2}(?!\d)", after)]
    net_lines = [parse_money(re.sub(r"^[^\d]*", "", x)) for x in re.findall(r"(?:Net Value|Amount):?\s*VND\s*\d[\d,.]*[.,]\d{2}", t, re.I)]
    m_per = re.search(r"[.,]\d{2}\s+(\d{1,4})\s", after)
    per = parse_int(m_per.group(1)) if m_per else 100

    qty = before[-1] if before else 0
    price_per = dec[0] if dec else 0.0
    net = dec[-1] if dec else 0.0
    votes = {}
    for v in [net] + net_lines:
        if v > 0:
            votes[v] = votes.get(v, 0) + 1
    if votes:
        net = sorted(votes.keys(), key=lambda k: votes[k], reverse=True)[0]

    price = price_per / per if per else 0.0
    ok = price > 0 and net > 0 and abs(qty * price - net) < 1.0
    if not ok and net > 0 and qty > 0:
        p2 = net / qty * per
        if abs(round(p2, 2) - p2) < 1e-6 and p2 > 0:
            price = p2 / per
            ok = True
    if not ok and net > 0 and price > 0:
        q2 = net / price
        if abs(q2 - round(q2)) < 1e-6:
            qty = int(round(q2))
            ok = True

    desc_m = re.search(r"CORE[^,]*", (lines[li + 2] if li + 2 < len(lines) else "") + " " + (lines[li + 1] if li + 1 < len(lines) else ""), re.I)
    return {"po": po, "code": code, "qty": qty, "price": price, "net": net, "check": ok, "desc": desc_m.group(0).strip() if desc_m else ""}


def parse_tesa_po_text(text, tesa_catalog, data_store=None):
    pages = [p.strip() for p in text.split("@@PAGE@@") if p.strip()]
    if not pages:
        pages = [text]
    found_lines = []
    for p in pages:
        res = parse_tesa_po_page(p)
        if not res:
            continue
        known = next((x for x in tesa_catalog if x["code"] == res["code"]), None)
        name = known["name"] if known else f"Ống lõi giấy {res['desc']} ({res['code']})"
        mem = data_store.get_item_norm(name) if data_store else None
        div = mem["div"] if (mem and mem.get("div")) else (known["div"] if known else 0)
        kg = mem["kg"] if (mem and mem.get("kg")) else (known["kg"] if known else 0)
        tare = known.get("tare", 1.0) if known else 1.0
        qty = res["qty"]
        price = res["price"] or (known["price"] if known else 0)
        kien = math.ceil(round(qty / div * 1e6) / 1e6) if div > 0 else 0
        net = round(qty * kg, 2) if kg > 0 else 0.0
        gross = round(net + tare, 2) if net > 0 else 0.0
        found_lines.append({
            "stt": len(found_lines) + 1,
            "po": res["po"],
            "hs": (mem.get("hs") if mem else None) or (known.get("hs", "48229090") if known else "48229090"),
            "ma_sp": res["code"],
            "ten_sp": name,
            "ten_hq": known.get("ten_hq", "") if known else "",
            "unit": known.get("unit", "ống") if known else "ống",
            "qty": qty,
            "price": price,
            "amount": round(qty * price),
            "div": div,
            "kg": kg,
            "kien": kien,
            "net": net,
            "gross": gross,
            "tare": tare,
        })
    first_po = found_lines[0]["po"] if found_lines else ""
    return first_po, found_lines


def parse_shirai_po_excel(file_path, data_store):
    wb = openpyxl.load_workbook(file_path, data_only=True)
    ws = wb.active
    rows = list(ws.iter_rows(values_only=True))
    po_no = "202637HT"
    for r in rows[:25]:
        txt = str(r[1] if len(r) > 1 and r[1] else "")
        if any(k in txt for k in ("Po.No", "PO No", "Purchase Order")):
            m = re.search(r"(?:Po\.No|PO No|No|:)\s*([A-Za-z0-9_-]+)", txt, re.I)
            if m:
                po_no = m.group(1).strip()
                break

    schedules = {}
    cur_cust_code = ""
    for r in rows:
        if len(r) < 8:
            continue
        c_code = str(r[1] or "").strip()
        raw_desc = str(r[4] or "")
        desc = re.sub(r"[\s\-–—(\[]*kh[ôo]ng\s*in[\s)\]]*", " ", raw_desc, flags=re.I)
        desc = re.sub(r"\s+", " ", desc).strip()
        s_date = r[5]
        try:
            qty = float(r[6] or 0)
            price = float(r[7] or 0)
        except Exception:
            qty, price = 0, 0
        if c_code:
            cur_cust_code = c_code
        if desc and desc.lower() not in ("total", "description") and qty > 0:
            date_key = "Chua_Xac_Dinh"
            date_str = datetime.date.today().strftime("%Y-%m-%d")
            if isinstance(s_date, (datetime.datetime, datetime.date)):
                date_key = s_date.strftime("%d.%m")
                date_str = s_date.strftime("%Y-%m-%d")
            elif isinstance(s_date, str) and len(s_date.strip()) >= 8:
                date_str = s_date.strip()[:10]
                parts = re.split(r"[-/]", date_str)
                if len(parts) == 3:
                    date_key = f"{parts[-1]}.{parts[1]}"

            if date_key not in schedules:
                schedules[date_key] = {"dateStr": date_str, "items": []}

            ck = clean_str(desc)
            erp_code = data_store.erp_map.get(ck, "")
            if not erp_code:
                for ek, val in data_store.erp_map.items():
                    if ck in ek or ek in ck:
                        erp_code = val
                        break

            w_kg = 0.0
            w_g = 0.0
            for wk, wobj in data_store.weights_db.items():
                w_clean = clean_str(wk)
                if w_clean == ck or ck in w_clean or w_clean in ck:
                    w_kg = float(wobj.get("kg") or 0.0)
                    w_g = float(wobj.get("g") or 0.0)
                    break

            final_name = desc
            if "carton box" in desc.lower() and not desc.lower().startswith("thùng"):
                final_name = "Thùng " + desc
            elif "pad" in desc.lower() and not desc.lower().startswith("tấm"):
                final_name = "Tấm lót " + desc

            net_w = round(qty * w_kg, 2) if w_kg else 0.0
            gross_w = round(net_w + 0.02, 2) if net_w > 0 else 0.0
            schedules[date_key]["items"].append({
                "stt": len(schedules[date_key]["items"]) + 1,
                "po": po_no,
                "hs": "",
                "ma_sp": erp_code,
                "ten_sp": final_name,
                "ten_hq": final_name,
                "unit": "cái",
                "qty": int(qty) if qty == int(qty) else qty,
                "price": price,
                "amount": round(qty * price),
                "div": 0,
                "kg": w_kg,
                "weight_g": w_g,
                "kien": 0,
                "net": net_w,
                "gross": gross_w,
                "tare": 0.02,
                "ma_kh": cur_cust_code,
            })

    for k, sdata in schedules.items():
        arr = sdata["items"]
        box_idx = next((i for i, x in enumerate(arr) if "Carton Box PNN-4585GHNA" in x["ten_sp"]), -1)
        pad_idx = next((i for i, x in enumerate(arr) if "Pad PNN-4585GH(AF_1:" in x["ten_sp"]), -1)
        if box_idx > pad_idx and pad_idx != -1:
            box_item = arr.pop(box_idx)
            arr.insert(pad_idx, box_item)
            for idx, it in enumerate(arr, 1):
                it["stt"] = idx

    return po_no, schedules


