class HongThienCustomsDesktopApp:
    def __init__(self, root, data_store):
        self.root = root
        self.store = data_store
        self.root.title("Phần Mềm Desktop Quét PO Offline & Lưu Trữ Hồ Sơ Hải Quan Tập Trung - Hồng Thiên")
        self.root.geometry("1450x880")
        self.root.minsize(1200, 740)
        self.root.configure(bg="#F4F6F9")

        self.cur_customer = tk.StringVar(value="kodi")
        self.cur_po = tk.StringVar(value="03102026-01KDHT")
        self.cur_po_date = tk.StringVar(value="03/10/2026")
        self.cur_doc_date = tk.StringVar(value=datetime.date.today().strftime("%Y-%m-%d"))
        self.cur_pxk = tk.StringVar(value="0000303")
        self.cur_hd = tk.StringVar(value="0000398")
        self.cur_tk = tk.StringVar(value="306889012340")
        self.cur_luong = tk.StringVar(value="Xanh")
        self.cur_xe = tk.StringVar(value="99C-158.08")
        self.cur_driver = tk.StringVar(value="Hồ Quang Hoàng")
        self.cur_ldd = tk.StringVar(value="03")
        self.cur_tare = tk.StringVar(value="1.0")
        self.kodi_skiph_var = tk.BooleanVar(value=False)
        self.tesa_batch_var = tk.StringVar(value="3010 (8 dòng)")
        self.shirai_sched_var = tk.StringVar(value="")
        self.shirai_schedules = {}
        self.cur_items = []
        self.step1_exported_paths = {}

        self.wb_rec = None
        self.wb_cust = tk.StringVar(value="kodi")
        self.wb_zone = tk.StringVar(value="WORKING")
        self.wb_date = tk.StringVar(value=datetime.date.today().strftime("%Y-%m-%d"))
        self.wb_po = tk.StringVar(value="")
        self.wb_pxk = tk.StringVar(value="")
        self.wb_hd = tk.StringVar(value="")
        self.wb_tk = tk.StringVar(value="")
        self.wb_luong = tk.StringVar(value="Xanh")
        self.wb_xe = tk.StringVar(value="")
        self.wb_slot_labels = {}

        self.setup_styles()
        self.build_ui()
